import sys

def solve():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]

    count = {'A': 0, 'C': 0, 'G': 0, 'T': 0}
    q_count = 0

    for char in s:
        if char == '?':
            q_count += 1
        else:
            count[char] += 1

    target = (n + 3) // 4
    if any(count[x] > target for x in count):
        print('===')
        return

    extra = sum(max(0, target - count[x]) for x in count)

    if extra != q_count:
        print('===')
        return

    result = []
    for char in s:
        if char != '?':
            result.append(char)
        else:
            for nucleotide in 'ACGT':
                if count[nucleotide] < target:
                    result.append(nucleotide)
                    count[nucleotide] += 1
                    break

    print(''.join(result))

solve()
